    public static IEnumerable<object[]> Cases() =>
        Reference.SelectMany(r => new[]
        {
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.Sunrise, r.Sunrise },
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.Sunset, r.Sunset },
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.CivilDawn, r.Dawn },
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.CivilDusk, r.Dusk },
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.NauticalDawn, r.NauticalDawn },
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.AstronomicalDusk, r.AstronomicalDusk },
            new object[] { r.Name, r.Lat, r.Lon, r.Zone, r.Date, SunEvent.SolarNoon, r.Noon },
        });

    [Theory]
    [MemberData(nameof(Cases))]
    public void Matches_reference_within_two_minutes(string place, double lat, double lon, string zoneId, string date, SunEvent sunEvent, string expected)
    {
        var zone = TimeZoneInfo.FindSystemTimeZoneById(zoneId);
        var actual = SolarCalculator.GetEvent(DateOnly.Parse(date), new GeoLocation(lat, lon), sunEvent, zone);

        if (expected == "null")
        {
            Assert.True(actual is null, $"{place} {date} {sunEvent}: expected none, got {actual}");
            return;
        }

        Assert.True(actual is not null, $"{place} {date} {sunEvent}: expected {expected}, got none");
        var reference = DateTimeOffset.Parse(expected);
        Assert.True(Math.Abs((actual!.Value - reference).TotalMinutes) <= 2, $"{place} {date} {sunEvent}: expected {expected}, got {actual:O}");
        Assert.Equal(reference.Offset, actual.Value.Offset); // reported in the place's local time
    }
